package example

import "errors"

var ErrBusy = errors.New("busy")

func IsPending(err error) bool {
	switch wrapped := err.(type) {
	case interface{ Unwrap() []error }:
		leaves := wrapped.Unwrap()
		for _, leaf := range leaves {
			if !IsPending(leaf) {
				return false
			}
		}
		return len(leaves) > 0
	case interface{ Unwrap() error }:
		return IsPending(wrapped.Unwrap())
	}
	return errors.Is(err, ErrBusy)
}

package example

import (
	"errors"
	"fmt"
	"testing"
)

var errDisk = errors.New("disk fault")

func TestPending(t *testing.T) {
	for name, err := range map[string]error{
		"marker":                ErrBusy,
		"wrapped marker":        fmt.Errorf("wrapped: %w", ErrBusy),
		"joined markers":        errors.Join(ErrBusy, fmt.Errorf("again: %w", ErrBusy)),
		"nested joined markers": errors.Join(ErrBusy, errors.Join(ErrBusy, fmt.Errorf("again: %w", ErrBusy))),
	} {
		if !IsPending(err) {
			t.Errorf("%s: want pending", name)
		}
	}
}

func TestJoinedFaultIsNotPending(t *testing.T) {
	for name, err := range map[string]error{
		"joined":             errors.Join(ErrBusy, errDisk),
		"wrapped joined":     fmt.Errorf("wrapped: %w", errors.Join(ErrBusy, errDisk)),
		"joined wrapped":     errors.Join(ErrBusy, fmt.Errorf("wrapped: %w", errDisk)),
		"nil":                nil,
		"plain fault":        errDisk,
		"distinct busy text": errors.New("busy"),
		"nested mixed join":  errors.Join(ErrBusy, errors.Join(ErrBusy, errDisk)),
		"multi wrapped":      fmt.Errorf("%w: %w", ErrBusy, errDisk),
	} {
		if IsPending(err) {
			t.Errorf("%s: a concrete fault is not pending", name)
		}
	}
}

